namespace Slice;

internal sealed record ExecutionOutcome(QueryResult? Result, string? ErrorMessage)
{
    public static ExecutionOutcome Success(QueryResult result)
    {
        return new ExecutionOutcome(result, null);
    }

    public static ExecutionOutcome Failure(string errorMessage)
    {
        return new ExecutionOutcome(null, errorMessage);
    }
}

internal abstract record QueryResult;

internal sealed record TableQueryResult(IReadOnlyList<string> Headers, IReadOnlyList<IReadOnlyList<string>> Rows) : QueryResult;

internal sealed record ScalarQueryResult(decimal Value) : QueryResult;

namespace Slice;

internal static class Program
{
    public static async Task<int> Main(string[] args)
    {
        var app = new SliceApplication(Console.OpenStandardOutput(), Console.Error);
        return await app.RunAsync(args);
    }
}

namespace Slice;

public sealed class SliceApplication
{
    private const string UsageMessage =
        "Usage: slice <csv-file> select <columns> | where <expression> | sort <column> [asc|desc] | head <count> | distinct <column> [<column>...] | count | sum <column> | groupby <column> count | groupby <column> sum <column> [--format csv|json|table]";

    private readonly Stream _output;
    private readonly TextWriter _error;
    private readonly CsvTableProcessor _csvProcessor = new();

    public SliceApplication(Stream output, TextWriter error)
    {
        _output = output ?? throw new ArgumentNullException(nameof(output));
        _error = error ?? throw new ArgumentNullException(nameof(error));
    }

    public async Task<int> RunAsync(IReadOnlyList<string> args)
    {
        if (!TryParseArguments(args, out var inputPath, out var command, out var commandArguments, out var outputFormat))
        {
            await _error.WriteLineAsync(UsageMessage).ConfigureAwait(false);
            return 1;
        }

        if (!File.Exists(inputPath))
        {
            await _error.WriteLineAsync($"File not found: {inputPath}").ConfigureAwait(false);
            return 1;
        }

        await using var input = File.OpenRead(inputPath);

        var outcome = command switch
        {
            "select" => ExecuteSelect(input, commandArguments),
            "where" => ExecuteWhere(input, commandArguments),
            "sort" => ExecuteSort(input, commandArguments),
            "head" => ExecuteHead(input, commandArguments),
            "distinct" => ExecuteDistinct(input, commandArguments),
            "count" => ExecuteCount(input),
            "sum" => ExecuteSum(input, commandArguments),
            "groupby" => ExecuteGroupBy(input, commandArguments),
            _ => ExecutionOutcome.Failure(UsageMessage)
        };

        if (outcome.ErrorMessage is not null)
        {
            await _error.WriteLineAsync(outcome.ErrorMessage).ConfigureAwait(false);
            return 1;
        }

        await OutputRenderer.RenderAsync(_output, outcome.Result!, outputFormat).ConfigureAwait(false);
        return 0;
    }

    private ExecutionOutcome ExecuteSelect(Stream input, IReadOnlyList<string> commandArguments)
    {
        IReadOnlyList<string> selectedColumns = _csvProcessor.ParseRequestedColumns(commandArguments);
        return _csvProcessor.SelectColumns(input, selectedColumns);
    }

    private ExecutionOutcome ExecuteWhere(Stream input, IReadOnlyList<string> commandArguments)
    {
        return _csvProcessor.FilterRows(input, commandArguments[0]);
    }

    private ExecutionOutcome ExecuteSort(Stream input, IReadOnlyList<string> commandArguments)
    {
        return _csvProcessor.SortRows(input, commandArguments[0], commandArguments.Count > 1 ? commandArguments[1] : null);
    }

    private ExecutionOutcome ExecuteHead(Stream input, IReadOnlyList<string> commandArguments)
    {
        return _csvProcessor.HeadRows(input, commandArguments[0]);
    }

    private ExecutionOutcome ExecuteDistinct(Stream input, IReadOnlyList<string> commandArguments)
    {
        IReadOnlyList<string> distinctColumns = _csvProcessor.ParseRequestedColumns(commandArguments);
        return _csvProcessor.DistinctRows(input, distinctColumns);
    }

    private ExecutionOutcome ExecuteCount(Stream input)
    {
        return _csvProcessor.CountRows(input);
    }

    private ExecutionOutcome ExecuteSum(Stream input, IReadOnlyList<string> commandArguments)
    {
        return _csvProcessor.SumRows(input, commandArguments[0]);
    }

    private ExecutionOutcome ExecuteGroupBy(Stream input, IReadOnlyList<string> commandArguments)
    {
        return _csvProcessor.GroupRows(input, commandArguments);
    }

    private static bool TryParseArguments(
        IReadOnlyList<string> args,
        out string inputPath,
        out string command,
        out IReadOnlyList<string> commandArguments,
        out OutputFormat outputFormat)
    {
        inputPath = string.Empty;
        command = string.Empty;
        commandArguments = Array.Empty<string>();
        outputFormat = OutputFormat.Csv;

        if (args.Count < 2)
        {
            return false;
        }

        inputPath = args[0];

        var remainingArguments = new List<string>();
        var formatSpecified = false;

        for (var i = 1; i < args.Count; i++)
        {
            var current = args[i];
            if (string.Equals(current, "--format", StringComparison.OrdinalIgnoreCase))
            {
                if (formatSpecified || i + 1 >= args.Count || !TryParseOutputFormat(args[i + 1], out outputFormat))
                {
                    return false;
                }

                formatSpecified = true;
                i++;
                continue;
            }

            remainingArguments.Add(current);
        }

        if (remainingArguments.Count == 0)
        {
            return false;
        }

        command = remainingArguments[0];
        commandArguments = remainingArguments.Count > 1 ? remainingArguments.Skip(1).ToArray() : Array.Empty<string>();

        return command switch
        {
            "select" or "where" or "head" => commandArguments.Count == 1,
            "sort" => commandArguments.Count is 1 or 2,
            "distinct" => commandArguments.Count >= 1,
            "count" => commandArguments.Count == 0,
            "sum" => commandArguments.Count == 1,
            "groupby" => commandArguments.Count is 2 or 3,
            _ => false
        };
    }

    private static bool TryParseOutputFormat(string value, out OutputFormat outputFormat)
    {
        if (string.Equals(value, "csv", StringComparison.OrdinalIgnoreCase))
        {
            outputFormat = OutputFormat.Csv;
            return true;
        }

        if (string.Equals(value, "json", StringComparison.OrdinalIgnoreCase))
        {
            outputFormat = OutputFormat.Json;
            return true;
        }

        if (string.Equals(value, "table", StringComparison.OrdinalIgnoreCase))
        {
            outputFormat = OutputFormat.Table;
            return true;
        }

        outputFormat = default;
        return false;
    }
}

using System.Globalization;
using System.Text;
using System.Text.Json;

namespace Slice;

internal enum OutputFormat
{
    Csv,
    Json,
    Table
}

internal static class OutputRenderer
{
    public static async Task RenderAsync(Stream output, QueryResult result, OutputFormat format)
    {
        switch (format)
        {
            case OutputFormat.Csv:
                await RenderCsvAsync(output, result).ConfigureAwait(false);
                return;
            case OutputFormat.Json:
                await RenderJsonAsync(output, result).ConfigureAwait(false);
                return;
            case OutputFormat.Table:
                await RenderTableAsync(output, result).ConfigureAwait(false);
                return;
            default:
                throw new ArgumentOutOfRangeException(nameof(format), format, null);
        }
    }

    private static async Task RenderCsvAsync(Stream output, QueryResult result)
    {
        await using var writer = CreateWriter(output);

        switch (result)
        {
            case TableQueryResult tableResult:
                await writer.WriteLineAsync(BuildCsvRow(tableResult.Headers)).ConfigureAwait(false);
                foreach (var row in tableResult.Rows)
                {
                    await writer.WriteLineAsync(BuildCsvRow(row)).ConfigureAwait(false);
                }
                break;
            case ScalarQueryResult scalarResult:
                await writer.WriteLineAsync(FormatDecimal(scalarResult.Value)).ConfigureAwait(false);
                break;
            default:
                throw new InvalidOperationException($"Unsupported result type: {result.GetType().Name}");
        }

        await writer.FlushAsync().ConfigureAwait(false);
        await output.FlushAsync().ConfigureAwait(false);
    }

    private static async Task RenderJsonAsync(Stream output, QueryResult result)
    {
        using var jsonWriter = new Utf8JsonWriter(output, new JsonWriterOptions
        {
            Indented = false,
            SkipValidation = false
        });

        switch (result)
        {
            case TableQueryResult tableResult:
                jsonWriter.WriteStartArray();
                foreach (var row in tableResult.Rows)
                {
                    jsonWriter.WriteStartObject();
                    for (var i = 0; i < tableResult.Headers.Count; i++)
                    {
                        var header = tableResult.Headers[i];
                        var value = i < row.Count ? row[i] : string.Empty;
                        jsonWriter.WriteString(header, value);
                    }
                    jsonWriter.WriteEndObject();
                }
                jsonWriter.WriteEndArray();
                break;
            case ScalarQueryResult scalarResult:
                jsonWriter.WriteNumberValue(scalarResult.Value);
                break;
            default:
                throw new InvalidOperationException($"Unsupported result type: {result.GetType().Name}");
        }

        await jsonWriter.FlushAsync().ConfigureAwait(false);
        await output.FlushAsync().ConfigureAwait(false);
    }

    private static async Task RenderTableAsync(Stream output, QueryResult result)
    {
        await using var writer = CreateWriter(output);

        switch (result)
        {
            case TableQueryResult tableResult:
                var widths = GetColumnWidths(tableResult.Headers, tableResult.Rows);
                await writer.WriteLineAsync(BuildTableRow(tableResult.Headers, widths)).ConfigureAwait(false);
                await writer.WriteLineAsync(BuildTableSeparator(widths)).ConfigureAwait(false);
                foreach (var row in tableResult.Rows)
                {
                    await writer.WriteLineAsync(BuildTableRow(row, widths)).ConfigureAwait(false);
                }
                break;
            case ScalarQueryResult scalarResult:
                await writer.WriteLineAsync(FormatDecimal(scalarResult.Value)).ConfigureAwait(false);
                break;
            default:
                throw new InvalidOperationException($"Unsupported result type: {result.GetType().Name}");
        }

        await writer.FlushAsync().ConfigureAwait(false);
        await output.FlushAsync().ConfigureAwait(false);
    }

    private static string BuildCsvRow(IReadOnlyList<string> fields)
    {
        var outputFields = new string[fields.Count];
        for (var i = 0; i < fields.Count; i++)
        {
            outputFields[i] = EscapeCsvField(fields[i]);
        }

        return string.Join(",", outputFields);
    }

    private static string BuildTableRow(IReadOnlyList<string> values, int[] widths)
    {
        var cells = new string[widths.Length];
        for (var i = 0; i < widths.Length; i++)
        {
            var value = i < values.Count ? values[i] : string.Empty;
            cells[i] = value.PadRight(widths[i]);
        }

        return string.Join(" | ", cells);
    }

    private static string BuildTableSeparator(int[] widths)
    {
        return string.Join("-+-", widths.Select(width => new string('-', width)));
    }

    private static int[] GetColumnWidths(IReadOnlyList<string> headers, IReadOnlyList<IReadOnlyList<string>> rows)
    {
        var widths = headers.Select(header => header.Length).ToArray();
        foreach (var row in rows)
        {
            for (var i = 0; i < widths.Length; i++)
            {
                var valueLength = i < row.Count ? row[i].Length : 0;
                if (valueLength > widths[i])
                {
                    widths[i] = valueLength;
                }
            }
        }

        return widths;
    }

    private static StreamWriter CreateWriter(Stream output)
    {
        return new StreamWriter(output, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false), leaveOpen: true)
        {
            NewLine = "\r\n"
        };
    }

    private static string EscapeCsvField(string value)
    {
        if (value.Length == 0)
        {
            return string.Empty;
        }

        var requiresQuoting = value.Contains(',') ||
            value.Contains('"') ||
            value.Contains('\r') ||
            value.Contains('\n');

        if (!requiresQuoting)
        {
            return value;
        }

        var escaped = value.Replace("\"", "\"\"");
        return $"\"{escaped}\"";
    }

    private static string FormatDecimal(decimal value)
    {
        return value.ToString("0.#############################", CultureInfo.InvariantCulture);
    }
}

using System.Globalization;
using System.Text;
using Microsoft.VisualBasic.FileIO;

namespace Slice;

internal sealed class CsvTableProcessor
{
    public IReadOnlyList<string> ParseRequestedColumns(string columnsArgument)
    {
        return ParseRequestedColumns(new[] { columnsArgument });
    }

    public IReadOnlyList<string> ParseRequestedColumns(IEnumerable<string> columnArguments)
    {
        var requestedColumns = new List<string>();

        foreach (var columnArgument in columnArguments)
        {
            if (string.IsNullOrWhiteSpace(columnArgument))
            {
                continue;
            }

            requestedColumns.AddRange(
                columnArgument.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries));
        }

        return requestedColumns;
    }

    public ExecutionOutcome SelectColumns(
        Stream input,
        IReadOnlyList<string> requestedColumns)
    {
        if (requestedColumns.Count == 0)
        {
            return ExecutionOutcome.Failure("No columns were selected.");
        }

        using var parser = new TextFieldParser(input, Encoding.UTF8)
        {
            TextFieldType = FieldType.Delimited,
            HasFieldsEnclosedInQuotes = true,
            TrimWhiteSpace = false
        };

        parser.SetDelimiters(",");

        var headers = parser.ReadFields();
        if (headers is null)
        {
            return ExecutionOutcome.Failure("CSV file is empty.");
        }

        if (!TryResolveRequestedColumnIndexes(headers, requestedColumns, out var selectedIndexes, out var errorMessage))
        {
            return ExecutionOutcome.Failure(errorMessage!);
        }

        var selectedHeaders = selectedIndexes.Select(index => headers[index]).ToArray();
        var rows = new List<IReadOnlyList<string>>();

        while (!parser.EndOfData)
        {
            var fields = parser.ReadFields();
            if (fields is null)
            {
                continue;
            }

            rows.Add(BuildSelectedRow(fields, selectedIndexes));
        }

        return ExecutionOutcome.Success(new TableQueryResult(selectedHeaders, rows));
    }

    public ExecutionOutcome DistinctRows(
        Stream input,
        IReadOnlyList<string> requestedColumns)
    {
        if (requestedColumns.Count == 0)
        {
            return ExecutionOutcome.Failure("No columns were selected.");
        }

        using var parser = CreateParser(input);

        var headers = parser.ReadFields();
        if (headers is null)
        {
            return ExecutionOutcome.Failure("CSV file is empty.");
        }

        if (!TryResolveRequestedColumnIndexes(headers, requestedColumns, out var selectedIndexes, out var errorMessage))
        {
            return ExecutionOutcome.Failure(errorMessage!);
        }

        var seenRows = new HashSet<string[]>(new StringArraySequenceComparer());
        var rows = new List<IReadOnlyList<string>>();

        while (!parser.EndOfData)
        {
            var fields = parser.ReadFields();
            if (fields is null)
            {
                continue;
            }

            var distinctKey = BuildDistinctKey(fields, selectedIndexes);
            if (!seenRows.Add(distinctKey))
            {
                continue;
            }

            rows.Add(BuildSelectedRow(fields, selectedIndexes));
        }

        var selectedHeaders = selectedIndexes.Select(index => headers[index]).ToArray();
        return ExecutionOutcome.Success(new TableQueryResult(selectedHeaders, rows));
    }

    public ExecutionOutcome FilterRows(
        Stream input,
        string whereExpression)
    {
        if (!CsvWhereClause.TryParse(whereExpression, out var clause, out var errorMessage))
        {
            return ExecutionOutcome.Failure(errorMessage);
        }

        using var parser = CreateParser(input);

        var headers = parser.ReadFields();
        if (headers is null)
        {
            return ExecutionOutcome.Failure("CSV file is empty.");
        }

        var filteredColumnIndex = Array.FindIndex(
            headers,
            header => string.Equals(header, clause.ColumnName, StringComparison.OrdinalIgnoreCase));

        if (filteredColumnIndex < 0)
        {
            return ExecutionOutcome.Failure($"Column not found: {clause.ColumnName}");
        }

        var rows = new List<IReadOnlyList<string>>();

        while (!parser.EndOfData)
        {
            var fields = parser.ReadFields();
            if (fields is null)
            {
                continue;
            }

            var candidateValue = filteredColumnIndex < fields.Length ? fields[filteredColumnIndex] : string.Empty;
            if (!clause.Matches(candidateValue))
            {
                continue;
            }

            rows.Add(fields);
        }

        return ExecutionOutcome.Success(new TableQueryResult(headers, rows));
    }

    public ExecutionOutcome SortRows(
        Stream input,
        string columnName,
        string? directionArgument)
    {
        if (!TryParseSortDirection(directionArgument, out var sortDirection, out var errorMessage))
        {
            return ExecutionOutcome.Failure(errorMessage!);
        }

        using var parser = CreateParser(input);

        var headers = parser.ReadFields();
        if (headers is null)
        {
            return ExecutionOutcome.Failure("CSV file is empty.");
        }

        var sortColumnIndex = Array.FindIndex(
            headers,
            header => string.Equals(header, columnName, StringComparison.OrdinalIgnoreCase));

        if (sortColumnIndex < 0)
        {
            return ExecutionOutcome.Failure($"Column not found: {columnName}");
        }

        var rows = new List<CsvRow>();
        while (!parser.EndOfData)
        {
            var fields = parser.ReadFields();
            if (fields is null)
            {
                continue;
            }

            rows.Add(new CsvRow(fields, GetSortValue(fields, sortColumnIndex)));
        }

        var allRowsAreNumeric = rows.All(row => row.SortValue.IsNumeric);
        var orderedRows = allRowsAreNumeric
            ? sortDirection == SortDirection.Ascending
                ? rows.OrderBy(row => row.SortValue.NumericValue)
                : rows.OrderByDescending(row => row.SortValue.NumericValue)
            : sortDirection == SortDirection.Ascending
                ? rows.OrderBy(row => row.SortValue.TextValue, StringComparer.Ordinal)
                : rows.OrderByDescending(row => row.SortValue.TextValue, StringComparer.Ordinal);

        var sortedRows = orderedRows.Select(row => row.Fields).ToArray();
        return ExecutionOutcome.Success(new TableQueryResult(headers, sortedRows));
    }

    public ExecutionOutcome HeadRows(
        Stream input,
        string rowCountArgument)
    {
        if (!TryParsePositiveRowCount(rowCountArgument, out var rowCount, out var errorMessage))
        {
            return ExecutionOutcome.Failure(errorMessage!);
        }

