 16	        _error = error ?? throw new ArgumentNullException(nameof(error));
 17	    }
 18	
 19	    public async Task<int> RunAsync(IReadOnlyList<string> args)
 20	    {
 21	        if (!TryParseArguments(args, out var inputPath, out var commands, out var outputFormat))
 22	        {
 23	            await _error.WriteLineAsync(UsageMessage).ConfigureAwait(false);
 24	            return 1;
 25	        }
 26	
 27	        if (!File.Exists(inputPath))
 28	        {
 29	            await _error.WriteLineAsync($"File not found: {inputPath}").ConfigureAwait(false);
 30	            return 1;
 31	        }
 32	
 33	        await using var input = File.OpenRead(inputPath);
 34	
 35	        var loadOutcome = _csvProcessor.LoadTable(input);
 36	        if (loadOutcome.ErrorMessage is not null)
 37	        {
 38	            await _error.WriteLineAsync(loadOutcome.ErrorMessage).ConfigureAwait(false);
 39	            return 1;
 40	        }
 41	
 42	        QueryResult currentResult = loadOutcome.Result!;
 43	        foreach (var command in commands)
 44	        {
 45	            var outcome = _csvProcessor.ApplyCommand(currentResult, command.Name, command.Arguments);
 46	            if (outcome.ErrorMessage is not null)
 47	            {
 48	                await _error.WriteLineAsync(outcome.ErrorMessage).ConfigureAwait(false);
 49	                return 1;
 50	            }
 51	
 52	            currentResult = outcome.Result!;
 53	        }
 54	
 55	        await OutputRenderer.RenderAsync(_output, currentResult, outputFormat).ConfigureAwait(false);
 56	        return 0;
 57	    }
