 59	    private static bool TryParseArguments(
 60	        IReadOnlyList<string> args,
 61	        out string inputPath,
 62	        out IReadOnlyList<PipelineCommand> commands,
 63	        out OutputFormat outputFormat)
 64	    {
 65	        inputPath = string.Empty;
 66	        commands = Array.Empty<PipelineCommand>();
 67	        outputFormat = OutputFormat.Csv;
 68	
 69	        if (args.Count < 2)
 70	        {
 71	            return false;
 72	        }
 73	
 74	        inputPath = args[0];
 75	
 76	        var remainingArguments = new List<string>();
 77	        var formatSpecified = false;
 78	
 79	        for (var i = 1; i < args.Count; i++)
 80	        {
 81	            var current = args[i];
 82	            if (string.Equals(current, "--format", StringComparison.OrdinalIgnoreCase))
 83	            {
 84	                if (formatSpecified || i + 1 >= args.Count || !TryParseOutputFormat(args[i + 1], out outputFormat))
 85	                {
 86	                    return false;
 87	                }
 88	
 89	                formatSpecified = true;
 90	                i++;
 91	                continue;
 92	            }
 93	
 94	            remainingArguments.Add(current);
 95	        }
 96	
 97	        if (remainingArguments.Count == 0)
 98	        {
 99	            return false;
100	        }
101	
102	        var pipelineTokens = remainingArguments.ToArray();
103	        if (pipelineTokens.Length == 0)
104	        {
105	            return false;
106	        }
107	
108	        if (!TryParsePipelineCommands(pipelineTokens, out commands))
109	        {
110	            return false;
111	        }
112	
113	        return commands.Count > 0;
114	    }
115	
116	    private static bool TryParseOutputFormat(string value, out OutputFormat outputFormat)
117	    {
118	        if (string.Equals(value, "csv", StringComparison.OrdinalIgnoreCase))
119	        {
120	            outputFormat = OutputFormat.Csv;
121	            return true;
122	        }
123	
124	        if (string.Equals(value, "json", StringComparison.OrdinalIgnoreCase))
125	        {
126	            outputFormat = OutputFormat.Json;
127	            return true;
128	        }
129	
130	        if (string.Equals(value, "table", StringComparison.OrdinalIgnoreCase))
131	        {
132	            outputFormat = OutputFormat.Table;
133	            return true;
134	        }
135	
136	        outputFormat = default;
137	        return false;
138	    }
139	
140	    private static bool TryParsePipelineCommands(
141	        IReadOnlyList<string> pipelineTokens,
142	        out IReadOnlyList<PipelineCommand> commands)
143	    {
144	        var parsedCommands = new List<PipelineCommand>();
145	        var currentTokens = new List<string>();
146	
147	        foreach (var token in pipelineTokens)
148	        {
149	            if (string.Equals(token, "|", StringComparison.Ordinal))
150	            {
151	                if (!TryAddParsedCommand(currentTokens, parsedCommands))
152	                {
153	                    commands = Array.Empty<PipelineCommand>();
154	                    return false;
155	                }
156	
157	                currentTokens.Clear();
158	                continue;
159	            }
160	
161	            currentTokens.Add(token);
162	        }
163	
164	        if (!TryAddParsedCommand(currentTokens, parsedCommands))
165	        {
166	            commands = Array.Empty<PipelineCommand>();
167	            return false;
168	        }
169	
170	        commands = parsedCommands;
171	        return commands.Count > 0;
172	    }
173	
174	    private static bool TryAddParsedCommand(
175	        IReadOnlyList<string> commandTokens,
176	        ICollection<PipelineCommand> commands)
177	    {
178	        if (commandTokens.Count == 0)
179	        {
180	            return false;
181	        }
182	
183	        var commandName = commandTokens[0];
184	        var commandArguments = commandTokens.Count > 1
185	            ? commandTokens.Skip(1).ToArray()
186	            : Array.Empty<string>();
187	
188	        if (!IsValidCommandShape(commandName, commandArguments))
189	        {
190	            return false;
191	        }
192	
193	        commands.Add(new PipelineCommand(commandName, commandArguments));
194	        return true;
195	    }
196	
197	    private static bool IsValidCommandShape(string commandName, IReadOnlyList<string> commandArguments)
198	    {
199	        return commandName switch
200	        {
201	            "select" or "where" or "head" => commandArguments.Count == 1,
202	            "sort" => commandArguments.Count is 1 or 2,
203	            "distinct" => commandArguments.Count >= 1,
204	            "count" => commandArguments.Count == 0,
205	            "sum" => commandArguments.Count == 1,
206	            "groupby" => commandArguments.Count is 2 or 3,
207	            _ => false
208	        };
209	    }
210	
211	    private sealed record PipelineCommand(string Name, IReadOnlyList<string> Arguments);
212	}

