  9	    public ExecutionOutcome LoadTable(Stream input)
 10	    {
 11	        using var parser = CreateParser(input);
 12	
 13	        var headers = parser.ReadFields();
 14	        if (headers is null)
 15	        {
 16	            return ExecutionOutcome.Failure("CSV file is empty.");
 17	        }
 18	
 19	        var rows = new List<IReadOnlyList<string>>();
 20	        while (!parser.EndOfData)
 21	        {
 22	            var fields = parser.ReadFields();
 23	            if (fields is null)
 24	            {
 25	                continue;
 26	            }
 27	
 28	            rows.Add(fields);
 29	        }
 30	
 31	        return ExecutionOutcome.Success(new TableQueryResult(headers, rows));
 32	    }
