 34	    public ExecutionOutcome ApplyCommand(
 35	        QueryResult current,
 36	        string commandName,
 37	        IReadOnlyList<string> commandArguments)
 38	    {
 39	        if (current is not TableQueryResult table)
 40	        {
 41	            return ExecutionOutcome.Failure($"Command cannot operate on scalar result: {commandName}");
 42	        }
 43	
 44	        return commandName switch
 45	        {
 46	            "select" => SelectColumns(table, ParseRequestedColumns(commandArguments)),
 47	            "where" => FilterRows(table, commandArguments[0]),
 48	            "sort" => SortRows(table, commandArguments[0], commandArguments.Count > 1 ? commandArguments[1] : null),
 49	            "head" => HeadRows(table, commandArguments[0]),
 50	            "distinct" => DistinctRows(table, ParseRequestedColumns(commandArguments)),
 51	            "count" => CountRows(table),
 52	            "sum" => SumRows(table, commandArguments[0]),
 53	            "groupby" => GroupRows(table, commandArguments),
 54	            _ => ExecutionOutcome.Failure($"Unknown command: {commandName}")
 55	        };
 56	    }
