 63	    public IReadOnlyList<string> ParseRequestedColumns(IEnumerable<string> columnArguments)
 64	    {
 65	        var requestedColumns = new List<string>();
 66	
 67	        foreach (var columnArgument in columnArguments)
 68	        {
 69	            if (string.IsNullOrWhiteSpace(columnArgument))
 70	            {
 71	                continue;
 72	            }
 73	
 74	            requestedColumns.AddRange(
 75	                columnArgument.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries));
 76	        }
 77	
 78	        return requestedColumns;
 79	    }
