 94	    private ExecutionOutcome SelectColumns(
 95	        TableQueryResult table,
 96	        IReadOnlyList<string> requestedColumns)
 97	    {
 98	        if (requestedColumns.Count == 0)
 99	        {
100	            return ExecutionOutcome.Failure("No columns were selected.");
101	        }
102	
103	        if (!TryResolveRequestedColumnIndexes(table.Headers, requestedColumns, out var selectedIndexes, out var errorMessage))
104	        {
105	            return ExecutionOutcome.Failure(errorMessage!);
106	        }
107	
108	        var selectedHeaders = selectedIndexes.Select(index => table.Headers[index]).ToArray();
109	        var rows = new List<IReadOnlyList<string>>();
110	        foreach (var row in table.Rows)
111	        {
112	            rows.Add(BuildSelectedRow(row, selectedIndexes));
113	        }
114	
115	        return ExecutionOutcome.Success(new TableQueryResult(selectedHeaders, rows));
116	    }
