131	    private ExecutionOutcome DistinctRows(
132	        TableQueryResult table,
133	        IReadOnlyList<string> requestedColumns)
134	    {
135	        if (requestedColumns.Count == 0)
136	        {
137	            return ExecutionOutcome.Failure("No columns were selected.");
138	        }
139	
140	        if (!TryResolveRequestedColumnIndexes(table.Headers, requestedColumns, out var selectedIndexes, out var errorMessage))
141	        {
142	            return ExecutionOutcome.Failure(errorMessage!);
143	        }
144	
145	        var seenRows = new HashSet<string[]>(new StringArraySequenceComparer());
146	        var rows = new List<IReadOnlyList<string>>();
147	        foreach (var row in table.Rows)
148	        {
149	            var distinctKey = BuildDistinctKey(row, selectedIndexes);
150	            if (!seenRows.Add(distinctKey))
151	            {
152	                continue;
153	            }
154	
155	            rows.Add(BuildSelectedRow(row, selectedIndexes));
156	        }
157	
158	        var selectedHeaders = selectedIndexes.Select(index => table.Headers[index]).ToArray();
159	        return ExecutionOutcome.Success(new TableQueryResult(selectedHeaders, rows));
160	    }
