175	    private ExecutionOutcome FilterRows(
176	        TableQueryResult table,
177	        string whereExpression)
178	    {
179	        if (!CsvWhereClause.TryParse(whereExpression, out var clause, out var errorMessage))
180	        {
181	            return ExecutionOutcome.Failure(errorMessage);
182	        }
183	
184	        var filteredColumnIndex = Array.FindIndex(
185	            table.Headers.ToArray(),
186	            header => string.Equals(header, clause.ColumnName, StringComparison.OrdinalIgnoreCase));
187	
188	        if (filteredColumnIndex < 0)
189	        {
190	            return ExecutionOutcome.Failure($"Column not found: {clause.ColumnName}");
191	        }
192	
193	        var rows = new List<IReadOnlyList<string>>();
194	        foreach (var fields in table.Rows)
195	        {
196	            var candidateValue = filteredColumnIndex < fields.Count ? fields[filteredColumnIndex] : string.Empty;
197	            if (!clause.Matches(candidateValue))
198	            {
199	                continue;
200	            }
201	
202	            rows.Add(fields);
203	        }
204	
205	        return ExecutionOutcome.Success(new TableQueryResult(table.Headers, rows));
206	    }
